messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87ceeb); // sky blue

        // Camera
        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 1, 0);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 1.2);
        scene.add(hemiLight);
        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(5, 10, 7);
        scene.add(dirLight);

        // Ground (simple plane)
        const groundGeo = new THREE.PlaneGeometry(200, 100);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228b22 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        scene.add(ground);

        // Finish line (visible as a white line)
        const finishLineGeo = new THREE.PlaneGeometry(200, 0.5);
        const finishLineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.position.y = 0.01;
        finishLine.position.z = 0;
        scene.add(finishLine);

        // Car models (using box geometry as placeholder)
        const redCarGeo = new THREE.BoxGeometry(4, 2, 8);
        const redCarMat = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const redCar = new THREE.Mesh(redCarGeo, redCarMat);
        redCar.position.set(-8, 1, 0);
        scene.add(redCar);

        const blueCarGeo = new THREE.BoxGeometry(4, 2, 8);
        const blueCarMat = new THREE.MeshStandardMaterial({ color: 0x0000ff });
        const blueCar = new THREE.Mesh(blueCarGeo, blueCarMat);
        blueCar.position.set(-8, 1, 5); // blue starts ahead
        scene.add(blueCar);

        // Race parameters
        const speedRed = 0.02; // initial speed
        const speedBlue = 0.03;
        let raceRunning = true;

        // Reset function
        function resetRace() {
            redCar.position.set(-8, 1, 0);
            blueCar.position.set(-8, 1, 5);
            // Reset velocities (z-axis)
            redCar.userData.vel = speedRed;
            blueCar.userData.vel = speedBlue;
        }

        // Animation loop
        function animate() {
            if (!raceRunning) {
                // Loop forever
                resetRace();
                raceRunning = true;
            }

            // Move cars forward
            redCar.position.z += redCar.userData.vel;
            blueCar.position.z += blueCar.userData.vel;

            // Acceleration logic: blue leads early, red accelerates to overtake
            if (blueCar.position.z < 0) {
                // Blue is ahead but slowing down slightly
                blueCar.userData.vel = speedBlue * 0.8;
                redCar.userData.vel = speedRed * 1.5;
            } else {
                // Red catches up and overtakes
                redCar.userData.vel = speedRed * 2.0;
                blueCar.userData.vel = speedBlue * 0.5;
            }

            // Check finish line (crossing z = 0)
            if (redCar.position.z >= 0) {
                raceRunning = false; // Stop race
                // Celebrate briefly (scale up red car)
                redCar.scale.set(1.2, 1.2, 1.2);
                setTimeout(() => {
                    redCar.scale.set(1, 1, 1);
                }, 500);
            }

            // Camera follows both cars (centered on midpoint)
            const midpoint = (redCar.position.z + blueCar.position.z) / 2;
            camera.position.z = midpoint - 5;

            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        resetRace();
        animate();
    </script>
</body>
</html>
```
